# Generate the twelve monthly periods of a fiscal year. Validate first so a bad year is a 400 and
# writes nothing; it hands the fiscal year's months to the period generator.
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: generate
# Each month left out when its name is taken or its days overlap a period; audits each one made.
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
  govern: [ transaction ]
# Paste lines of name,period,amount: each adds its amount to the person's (by name or alias) opening
# balance for the period, carried into it. Every line is checked before any is saved: one refused
# line refuses the paste and writes nothing.
validate:
  class: net.officefloor.hq.app.period.ValidateImportOpenings
  next: set
set:
  class: net.officefloor.hq.app.period.SetImportedOpenings
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithImportOpenings
  govern: [ transaction ]
