package net.officefloor.hq.app.period;

import java.time.YearMonth;
import java.util.regex.Pattern;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A fiscal year generate needs a year (yyyy). Fiscal year FY<yyyy> runs twelve months from the
 *  sheet's fiscal start month of yyyy; it is published as the generate of those months, so the
 *  months are made exactly as the period generator makes them. */
public class ValidateGenerateFiscalYear {
    private static final Pattern YEAR = Pattern.compile("\\d{4}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFiscalYearRequest request,
            Settings settings, Out<GeneratePeriodsRequest> body) throws InvalidSheetRequestException {
        String year = request == null || request.year() == null ? "" : request.year().trim();
        if (!YEAR.matcher(year).matches()) {
            throw new InvalidSheetRequestException("A fiscal year must be a year (yyyy)");
        }
        YearMonth first = YearMonth.of(Integer.parseInt(year), settings.fiscalStartMonth(sheetId));
        YearMonth last = first.plusMonths(11);
        body.set(new GeneratePeriodsRequest(first.atDay(1).toString(), last.atEndOfMonth().toString(), request.user()));
    }
}
package net.officefloor.hq.app.period;

/** Body of a fiscal year generate: the fiscal year (yyyy, the calendar year its first day falls in)
 *  whose twelve months get a period each, and who generates them. */
public record GenerateFiscalYearRequest(String year, String user) {
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Splits the paste into lines of name,period,amount and checks each line's form: a name, a period
 *  and an amount of two decimals, 0.00 or more; blank lines are skipped. One refused line refuses
 *  the whole paste. */
public class ValidateImportOpenings {
    private static final Pattern AMOUNT = Pattern.compile("\\d+\\.\\d{2}");

    public void validate(@RequestBody ImportOpeningsRequest request, Out<ImportedOpenings> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String user = request == null ? null : request.user();
        String text = request == null || request.text() == null ? "" : request.text();
        List<OpeningLine> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n")) {
            n++;
            if (raw.isBlank()) continue;
            String[] f = raw.split(",", -1);
            if (f.length != 3 || f[0].isBlank() || f[1].isBlank()) {
                throw new InvalidSheetRequestException("Line " + n + ": expected name,period,amount");
            }
            String amount = f[2].trim();
            if (!AMOUNT.matcher(amount).matches()) {
                throw new InvalidSheetRequestException("Line " + n + ": the amount must have two decimals and be 0.00 or more");
            }
            lines.add(new OpeningLine(n, f[0].trim(), f[1].trim(), new BigDecimal(amount)));
        }
        if (lines.isEmpty()) throw new InvalidSheetRequestException("Paste at least one line of name,period,amount");
        actor.set(new Actor(user));
        body.set(new ImportedOpenings(lines));
    }
}
package net.officefloor.hq.app.period;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Finds every line's person (by name or alias) and period on the sheet before any is set, so one
 *  line naming neither refuses the paste and writes nothing; then adds each line's amount, in order,
 *  to the person's opening balance for the period, audited OPENING_SET. */
public class SetImportedOpenings {
    public void set(@PathVariable("sheetId") String sheetId, @Val ImportedOpenings imported, @Val Actor actor,
            People people, Periods periods, Audit audit, Out<ImportOpeningsResult> result)
            throws InvalidSheetRequestException {
